  const query = `
    UPDATE jobs
    SET status = 'processing', worker_id = $1, started_at = NOW()
    WHERE id = (
      SELECT id FROM jobs
      WHERE status = 'pending'
      ORDER BY priority DESC, created_at ASC
      FOR UPDATE SKIP LOCKED
      LIMIT 1
    )
    RETURNING *;
  `;
  const result = await client.query(query, [workerId]);
